package cz.mh.rallye.rallye_backend.participation;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import jakarta.servlet.http.Cookie;
import cz.mh.rallye.rallye_backend.participation.api.*;import cz.mh.rallye.rallye_backend.participation.application.StartCodeService;
import cz.mh.rallye.rallye_backend.identity.api.*;import cz.mh.rallye.rallye_backend.identity.application.*;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;
@WebMvcTest(StartCodeController.class) @Import({AuthConfiguration.class,AuthCookies.class,ApiErrors.class,StartCodePrivacyFilter.class})
class StartCodeHttpTest {
 @Autowired MockMvc mvc;@MockitoBean AuthService auth;@MockitoBean StartCodeService service;
 final UUID event=UUID.randomUUID(),registration=UUID.randomUUID(),code=UUID.randomUUID();final String token=new SecretTokens().create(),base="/api/v1/race-events/"+event+"/registrations/"+registration;final AuthService.Principal actor=new AuthService.Principal(UUID.randomUUID(),UUID.randomUUID(),false);
 @BeforeEach void login(){when(auth.authenticate(token)).thenReturn(actor);when(auth.authenticateReadOnly(token)).thenReturn(actor);when(auth.isAdministrator(actor)).thenReturn(true);}
 StartCodeService.CodeResult result(){return new StartCodeService.CodeResult(code,"ORIGINAL","AVAILABLE",1,"ABC123","0",Instant.EPOCH);}
 @Test void anonymousAndNonAdminCannotAccessAnyCodeEndpoint()throws Exception{mvc.perform(get(base+"/start-codes")).andExpect(status().isUnauthorized()).andExpect(header().string("Referrer-Policy","no-referrer"));when(auth.isAdministrator(actor)).thenReturn(false);for(String suffix:List.of("/start-codes","/start-codes/"+code))mvc.perform(get(base+suffix).header("Authorization","Bearer "+token)).andExpect(status().isForbidden());for(String suffix:List.of("/start-codes","/replacement-codes"))mvc.perform(post(base+suffix).header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"registrationVersion\":0}")).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void pairResponseMatchesContractWithoutLocation()throws Exception{var second=new StartCodeService.CodeResult(UUID.randomUUID(),"ORIGINAL","AVAILABLE",2,"XYZ789","0",Instant.EPOCH);when(service.originals(any(),any(),any(),any(),anyLong())).thenReturn(new StartCodeService.IssuedCodePair(registration,1,List.of(result(),second)));mvc.perform(post(base+"/start-codes").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"registrationVersion\":0}")).andExpect(status().isCreated()).andExpect(header().doesNotExist("Location")).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("Referrer-Policy","no-referrer")).andExpect(jsonPath("$.codes.length()").value(2)).andExpect(jsonPath("$.codes[0].code").value("ABC123")).andExpect(jsonPath("$.codes[1].code").value("XYZ789")).andExpect(jsonPath("$.registrationVersion").value(1));}
 @Test void replacementAcceptsOmittedZeroAndSignedInt64Strings()throws Exception{when(service.replacement(any(),any(),any(),any(),anyLong(),anyLong(),any())).thenReturn(new StartCodeService.IssuedCode(registration,2,result()));for(String value:List.of("",",\"pointsAdjustment\":\"-9223372036854775808\"",",\"pointsAdjustment\":\"9223372036854775807\""))mvc.perform(post(base+"/replacement-codes").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"registrationVersion\":1"+value+"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.code.id").value(code.toString()));verify(service).replacement(eq(actor),eq(event),eq(registration),any(),eq(1L),eq(0L),isNull());verify(service).replacement(eq(actor),eq(event),eq(registration),any(),eq(1L),eq(Long.MIN_VALUE),isNull());verify(service).replacement(eq(actor),eq(event),eq(registration),any(),eq(1L),eq(Long.MAX_VALUE),isNull());}
 @Test void listHasOnlyMetadataAndDetailCanHideUsedValue()throws Exception{when(service.list(actor,event,registration,0,50)).thenReturn(new StartCodeService.Page(List.of(new StartCodeService.CodeView(code,registration,"ORIGINAL","AVAILABLE",1,"0",Instant.EPOCH,null,null)),0,50,false));when(service.detail(actor,event,registration,code)).thenReturn(new StartCodeService.CodeDetail(code,registration,"ORIGINAL","USED",1,"0",Instant.EPOCH,Instant.EPOCH,UUID.randomUUID(),null));mvc.perform(get(base+"/start-codes").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].code").doesNotExist()).andExpect(jsonPath("$.hasMore").value(false));mvc.perform(get(base+"/start-codes/"+code).header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(jsonPath("$.code").isEmpty()).andExpect(jsonPath("$.state").value("USED"));}
 @Test void cookieIssuanceRequiresCsrf()throws Exception{when(service.originals(any(),any(),any(),any(),anyLong())).thenReturn(new StartCodeService.IssuedCodePair(registration,1,List.of()));var cookie=new Cookie(AuthCookies.NAME,token);mvc.perform(post(base+"/start-codes").cookie(cookie).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"registrationVersion\":0}")).andExpect(status().isForbidden()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(post(base+"/start-codes").cookie(cookie).with(csrf().asHeader()).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"registrationVersion\":0}")).andExpect(status().isCreated());verify(service,times(1)).originals(any(),any(),any(),any(),anyLong());}
 @Test void malformedUnknownNullAndOverflowInputsAre400()throws Exception{for(String body:List.of("null","{}","{\"registrationVersion\":-1}","{\"registrationVersion\":0.5}","{\"registrationVersion\":0,\"pointsAdjustment\":null}","{\"registrationVersion\":0,\"pointsAdjustment\":7}","{\"registrationVersion\":0,\"pointsAdjustment\":\"9223372036854775808\"}","{\"registrationVersion\":0,\"code\":\"ABC123\"}"))mvc.perform(post(base+"/replacement-codes").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body)).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_REQUEST"));mvc.perform(post(base+"/start-codes").header("Authorization","Bearer "+token).contentType("application/json").content("{\"registrationVersion\":0}")).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void safeErrorsHavePrivacyHeadersAndNoCodes()throws Exception{when(service.originals(any(),any(),any(),any(),anyLong())).thenThrow(new AuthFailure(409,"ORIGINAL_CODES_ALREADY_ISSUED"));mvc.perform(post(base+"/start-codes").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"registrationVersion\":0}")).andExpect(status().isConflict()).andExpect(header().string("Referrer-Policy","no-referrer")).andExpect(jsonPath("$.code").value("ORIGINAL_CODES_ALREADY_ISSUED")).andExpect(jsonPath("$.codes").doesNotExist());}
 @Test void regenerationIsNotImplemented()throws Exception{for(String suffix:List.of("/start-codes/"+code+"/regenerations"))mvc.perform(post(base+suffix).header("Authorization","Bearer "+token).with(csrf().asHeader()).contentType("application/json").content("{}")).andExpect(status().isNotFound());verifyNoInteractions(service);}
}
